// 1. 取得資料並處理成陣列
let staffList = items[0].json["帳務人員"];
let lineLinks = items[0].json["LINE官方通話"];

if (!Array.isArray(staffList)) staffList = [staffList];
if (!Array.isArray(lineLinks)) lineLinks = [lineLinks];

// 2. 資料清洗
const allStaff = [];
const seenStaff = new Set();

staffList.forEach((name, index) => {
  const staffName = String(name || "");
  if (staffName && !seenStaff.has(staffName)) {
    seenStaff.add(staffName);
    allStaff.push({
      name: staffName,
      link: String(lineLinks[index] || "https://line.me/")
    });
  }
});

// 3. 準確分組邏輯 (1, 2, 2, 2)
const findByExts = (extArray) => {
  return allStaff.filter(p => extArray.some(ext => p.name.includes(ext)));
};

const group1 = findByExts(["122"]);
const group2 = findByExts(["111", "112"]);
const group3 = findByExts(["113", "117"]);
const group4 = findByExts(["115", "116"]);

// 4. 生成泡泡函數
function createBubble(title, staffArray, isSpecial = false) {
  if (staffArray.length === 0) return null;

  const contents = [];
  staffArray.forEach((person, idx) => {
    // 帳務泡泡中，兩個人名之間的分隔線
    if (idx > 0) {
      contents.push({ "type": "separator", "margin": "xl" });
    }

    const personBox = {
      "type": "box",
      "layout": "vertical",
      "margin": "md",
      "contents": [
        {
          "type": "text",
          "text": person.name,
          "size": "lg",
          "weight": "bold",
          "color": "#333333",
          "align": "start",
          "wrap": true
        },
        {
          "type": "button",
          "action": {
            "type": "uri",
            "label": "LINE 通話",
            "uri": person.link.startsWith('http') ? person.link : "https://line.me/"
          },
          "style": "primary",
          "color": "#00B900",
          "height": "sm",
          "margin": "sm"
        }
      ]
    };

    // 如果是第一組 (設立變更)，在按鈕下方加入分隔線與三行詳細資訊
    if (isSpecial) {
      // 1. 加入跟其他泡泡一樣的分隔線
      contents.push(personBox); // 先放入人名與按鈕
      contents.push({ "type": "separator", "margin": "xl" }); // 中間加分隔線

      // 2. 建立下方的公司資訊區塊
      contents.push({
        "type": "box",
        "layout": "vertical",
        "margin": "lg",
        "spacing": "xs",
        "contents": [
          {
            "type": "text",
            "text": "🕒 營業時間 08:00~17:00",
            "size": "xs",
            "color": "#666666",
            "align": "start"
          },
          {
            "type": "text",
            "text": "📞 電話：03-4550678",
            "size": "xs",
            "color": "#666666",
            "align": "start"
          },
          {
            "type": "text",
            "text": "📍 桃園市中壢區元化路271巷28號5樓",
            "size": "xs",
            "color": "#666666",
            "align": "start",
            "wrap": true
          }
        ]
      });
    } else {
      // 一般帳務泡泡直接放入內容
      contents.push(personBox);
    }
  });

  return {
    "type": "bubble",
    "size": "hecto",
    "header": {
      "type": "box",
      "layout": "vertical",
      "contents": [
        {
          "type": "text",
          "text": title,
          "weight": "bold",
          "size": "lg",
          "color": isSpecial ? "#0367D3" : "#1DB446",
          "align": "start"
        }
      ]
    },
    "body": {
      "type": "box",
      "layout": "vertical",
      "paddingAll": "12px",
      "paddingBottom": isSpecial ? "12px" : "40px", 
      "contents": contents
    }
  };
}

// 5. 組合最終四個泡泡
const finalBubbles = [
  createBubble("🏢 公司商業設立變更", group1, true),
  createBubble("📞 帳務專員 (一)", group2),
  createBubble("📞 帳務專員 (二)", group3),
  createBubble("📞 帳務專員 (三)", group4)
].filter(b => b !== null);

const finalFlex = {
  "type": "carousel",
  "contents": finalBubbles
};

return {
  flexJsonString: JSON.stringify(finalFlex)
};

